'use strict';

// MODULES //

var tape = require( 'tape' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var ulpdiff = require( '@stdlib/number/float32/base/ulp-difference' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var randu = require( '@stdlib/random/base/randu' );
var EPS = require( '@stdlib/constants/float32/eps' );
var acoshf = require( './../lib' );


// FIXTURES //

var largerPositive = require( './fixtures/julia/larger_positive.json' );
var largePositive = require( './fixtures/julia/large_positive.json' );
var mediumPositive = require( './fixtures/julia/medium_positive.json' );
var hugePositive = require( './fixtures/julia/huge_positive.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof acoshf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function computes the hyperbolic arccosine on the interval `[1.0,3.0]`', function test( t ) {
	var expected;
	var v;
	var x;
	var i;
	var e;

	x = mediumPositive.x;
	expected = mediumPositive.expected;

	for ( i = 0; i < x.length; i++ ) {
		x[ i ] = f32( x[ i ] );
		v = acoshf( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( ulpdiff( v, e ) <= 6, true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function computes the hyperbolic arccosine on the interval `[3.0,28.0]`', function test( t ) {
	var expected;
	var v;
	var x;
	var i;
	var e;

	x = largePositive.x;
	expected = largePositive.expected;

	for ( i = 0; i < x.length; i++ ) {
		x[ i ] = f32( x[ i ] );
		v = acoshf( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( ulpdiff( v, e ) <= 1, true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function computes the hyperbolic arccosine on the interval `[28.0,100.0]`', function test( t ) {
	var expected;
	var v;
	var x;
	var i;
	var e;

	x = largerPositive.x;
	expected = largerPositive.expected;

	for ( i = 0; i < x.length; i++ ) {
		x[ i ] = f32( x[ i ] );
		v = acoshf( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( ulpdiff( v, e ) <= 1, true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function computes the hyperbolic arccosine for huge values', function test( t ) {
	var expected;
	var v;
	var x;
	var i;
	var e;

	x = hugePositive.x;
	expected = hugePositive.expected;

	for ( i = 0; i < x.length; i++ ) {
		x[ i ] = f32( x[ i ] );
		v = acoshf( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( ulpdiff( v, e ) <= 1, true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function returns `NaN` if provided a `NaN`', function test( t ) {
	var v = acoshf( NaN );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `NaN` if provided value less than `1`', function test( t ) {
	var v;
	var i;

	for ( i = 0; i < 1e3; i++ ) {
		v = f32( -f32( randu()*f32( 1.0e6) ) + f32( f32( 1.0) - EPS ) );
		t.strictEqual( isnanf( acoshf( v ) ), true, 'returns expected value when provided '+v );
	}
	t.end();
});
